module DFF (Q, D, CLK);

input D, CLK;
output Q;

parameter INIT = 1'b0;
reg Q_reg = INIT;
reg notifier;
wire Q_out;
wire gsrt = GSR.GSRO;

always @(gsrt)begin
	if(!gsrt)
		assign Q_reg = INIT;
	else
		deassign Q_reg;
end

always @(Q_out) begin
	Q_reg = Q_out;
end

ff ff_inst(Q_out, CLK, D, 1'b1, 1'b0, 1'b0, 1'b0, 1'b0,notifier);

assign Q = Q_reg;

specify

	(CLK => Q) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);

	$period (posedge CLK, 0:0:0);
    $width (posedge CLK, 0:0:0);
    $width (negedge CLK, 0:0:0);

    specparam PATHPULSE$ = 0;

endspecify

endmodule // DFF (positive clock edge)


module DFFE (Q, D, CLK, CE);

