//Latches
module DL (Q, D, G);

input D, G;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (G)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	if (G)
	    (D +=> Q) = (0, 0);
	(posedge G => (Q +: D)) = (0, 0);

	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);    
endspecify

endmodule // DL (high active latch)


module DLE (Q, D, G, CE);

input D, G, CE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or CE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if(G && CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, posedge CE, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge CE, 0:0:0, 0:0:0);

	if (G && CE)
	    (D +=> Q) = (0, 0);
	if (CE)
	    (posedge G => (Q +: D)) = (0, 0);
	if (G)
	    (posedge CE => (Q +: D)) = (0, 0);
endspecify

endmodule // DLE (high active latch; latch enable)


module DLC (Q, D, G, CLEAR);

input D, G, CLEAR;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or CLEAR or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (CLEAR)
		Q_reg <= 1'b0;
	else if (G)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);
	$recrem (negedge CLEAR, negedge G, 0:0:0, 0:0:0);

	if (!CLEAR && G)
	    (D +=> Q) = (0, 0);
	if (!CLEAR)
	    (posedge G => (Q +: D)) = (0, 0);
	(posedge CLEAR => (Q +: 1'b0)) = (0, 0);
endspecify

endmodule // DLC (high active latch; asynchronous clear)


module DLCE (Q, D, G, CE, CLEAR);

input D, G, CLEAR, CE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or CLEAR or CE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (CLEAR)
		Q_reg <= 1'b0;
	else if (G && CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	$setuphold (negedge G, posedge CE, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge CE, 0:0:0, 0:0:0);

	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge CLEAR, negedge G, 0:0:0, 0:0:0);

	if (!CLEAR && G && CE)
	    (D +=> Q) = (0, 0);
	if (!CLEAR && CE)
	    (posedge G => (Q +: D)) = (0, 0);
	if (!CLEAR && G)
	    (posedge CE => (Q +: D)) = (0, 0);
	(posedge CLEAR => (Q +: 1'b0)) = (0, 0);

endspecify
endmodule // DLCE (high active latch; asynchronous clear; latch enable)


module DLP (Q, D, G, PRESET);

input D, G, PRESET;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or PRESET or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (PRESET)
		Q_reg <= 1'b1;
	else if (G)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	if (!PRESET && G)
	    (D +=> Q) = (0, 0);
	if (!PRESET)
	    (posedge G => (Q +: D)) = (0, 0);
	(posedge PRESET => (Q +: 1'b1)) = (0, 0);
	$setuphold (negedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge PRESET, negedge G, 0:0:0, 0:0:0);
endspecify

