assign Q = Q_reg;

specify
	if (!CLEAR && !G)
	    (D +=> Q) = (0, 0);
	if (!CLEAR)
	    (negedge G => (Q +: D)) = (0, 0);
	(posedge CLEAR => (Q +: 1'b0)) = (0, 0);

	$setuphold (posedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge D, 0:0:0, 0:0:0);
	$recrem (negedge CLEAR, posedge G, 0:0:0, 0:0:0);
    
endspecify

endmodule // DLNC (low active latch; asynchronous clear)


module DLNCE (Q, D, G, CE, CLEAR);

input D, G, CLEAR, CE;
output Q;

parameter INIT = 1'b0;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or CLEAR or CE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (CLEAR)
		Q_reg <= 1'b0;
	else if (!G && CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	if (!CLEAR && !G && CE)
	    (D +=> Q) = (0, 0);
	if (!CLEAR && CE)
	    (negedge G => (Q +: D)) = (0, 0);
	if (!CLEAR && !G)
	    (posedge CE => (Q +: D)) = (0, 0);
	(posedge CLEAR => (Q +: 1'b0)) = (0, 0);

	$setuphold (posedge G, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge CE, 0:0:0, 0:0:0);

	$setuphold (posedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge CLEAR, posedge G, 0:0:0, 0:0:0);
endspecify

endmodule // DLNCE (low active latch; asynchronous clear; latch enable)


module DLNP (Q, D, G, PRESET);

input D, G, PRESET;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or PRESET or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (PRESET)
		Q_reg <= 1'b1;
	else if (!G)
		Q_reg <= D;
end

assign Q = Q_reg;

specify
	if (!PRESET && !G)
	    (D +=> Q) = (0, 0);
	if (!PRESET)
	    (negedge G => (Q +: D)) = (0, 0);
	(posedge PRESET => (Q +: 1'b1)) = (0, 0);

	$setuphold (posedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge PRESET, posedge G, 0:0:0, 0:0:0);

endspecify

endmodule // DLNP (low active latch; asynchronous preset)


module DLNPE (Q, D, G, CE, PRESET);

input D, G, PRESET, CE;
output Q;

parameter INIT = 1'b1;
reg Q_reg;
wire gsrt = GSR.GSRO;

initial Q_reg = INIT;

always @(D or G or PRESET or CE or gsrt) begin
	if (!gsrt)
		Q_reg <= INIT;
	else if (PRESET)
		Q_reg <= 1'b1;
	else if (!G && CE)
		Q_reg <= D;
end

assign Q = Q_reg;

specify

	$setuphold (posedge G, posedge CE, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge CE, 0:0:0, 0:0:0);

	$setuphold (posedge G, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge G, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge PRESET, posedge G, 0:0:0, 0:0:0);

	if (!PRESET && !G && CE)
	    (D +=> Q) = (0, 0);
	if (!PRESET && CE)
	    (negedge G => (Q +: D)) = (0, 0);
	if (!PRESET && !G)
	    (posedge CE => (Q +: D)) = (0, 0);
	(posedge PRESET => (Q +: 1'b1)) = (0, 0);
endspecify

endmodule // DLNPE (low active latch; asynchronous preset; latch enable)

// Inverter
module INV (O, I);

input  I;
output O;

assign O = !I;

specify

	(I => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify
        
endmodule // inv
//IOBs
module IBUF (O, I);

input  I;
output O;

buf IB (O, I);

specify

	(I => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify
        
endmodule //IBUF (input buffer)


module OBUF (O, I);

input  I;
output O;

buf OB (O, I);

specify

	(I => O) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify
    
endmodule //OBUF (output buffer)


module TBUF (O, I, OEN);

input I, OEN;
output O;

bufif0 TB (O, I, OEN); 

specify

   (I => O) = (0:0:0, 0:0:0);
   (OEN => O) = (0:0:0, 0:0:0);
   specparam PATHPULSE$ = 0;

endspecify

endmodule // TBUF (output buffer with tri-state control)


module IOBUF (O, IO, I, OEN);

input I,OEN;
output O;
inout IO;

