   (I => O) = (0:0:0, 0:0:0);
   (I => IO) = (0:0:0, 0:0:0);
   (IO => O) = (0:0:0, 0:0:0);
   (OEN => O) = (0:0:0, 0:0:0);
   (OEN => IO) = (0:0:0, 0:0:0);
   specparam PATHPULSE$ = 0;

endspecify
    
endmodule //IOBUF (inout buffer)


module IDDR(Q0, Q1, D, CLK);

input D;
input CLK;
output Q0;
output Q1;

parameter Q0_INIT = 1'b0;
parameter Q1_INIT = 1'b0;

wire gsrt = GSR.GSRO;

reg Q0_oreg, Q1_oreg,Q0_reg, Q1_reg;

initial begin
	Q0_reg = Q0_INIT;
	Q1_reg = Q1_INIT;
    Q0_oreg = Q0_INIT;
	Q1_oreg = Q1_INIT;
end

assign Q0 = Q0_reg;
assign Q1 = Q1_reg;

always @(gsrt) begin
	if(!gsrt) begin
		assign Q0_reg = Q0_INIT;
		assign Q1_reg = Q1_INIT;
        assign Q0_oreg = Q0_INIT;
		assign Q1_oreg = Q1_INIT;
	end
	else begin
		deassign Q0_reg;
		deassign Q1_reg;
        deassign Q0_oreg;
		deassign Q1_oreg;
	end
end

always @(posedge CLK) begin
	Q0_oreg <= D;
    Q0_reg <= Q0_oreg;
	Q1_reg <= Q1_oreg;

end

always @(negedge CLK) begin
	Q1_oreg <= D;
end

specify

    (CLK => Q0) = (0:0:0, 0:0:0);
    (CLK => Q1) = (0:0:0, 0:0:0);

    $setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge CLK, negedge D, 0:0:0, 0:0:0);
    
	$period (posedge CLK, 0:0:0);
    $width (posedge CLK, 0:0:0);
    $width (negedge CLK, 0:0:0);

   specparam PATHPULSE$ = 0;

endspecify

endmodule //IDDR (ddr input)


module IDDRC(Q0, Q1, D, CLK, CLEAR);

input D;
input CLK;
input CLEAR;
output Q0;
output Q1;

parameter Q0_INIT = 1'b0;
parameter Q1_INIT = 1'b0;

wire gsrt = GSR.GSRO;

reg Q0_oreg, Q1_oreg,Q0_reg, Q1_reg;

initial begin
	Q0_reg = Q0_INIT;
	Q1_reg = Q1_INIT;
    Q0_oreg = Q0_INIT;
	Q1_oreg = Q1_INIT;
end

assign Q0 = Q0_reg;
assign Q1 = Q1_reg;

always @(gsrt or CLEAR) begin
	if(!gsrt) begin
		assign Q0_reg = Q0_INIT;
		assign Q1_reg = Q1_INIT;
        assign Q0_oreg = Q0_INIT;
		assign Q1_oreg = Q1_INIT;
	end
	else if (CLEAR) begin
		assign Q0_reg = 1'b0;
		assign Q1_reg = 1'b0;
        assign Q0_oreg = 1'b0;
		assign Q1_oreg = 1'b0;
	end
	else begin
		deassign Q0_reg;
		deassign Q1_reg;
        deassign Q0_oreg;
		deassign Q1_oreg;
	end
end

always @(posedge CLK) begin
	Q0_oreg <= D;
    Q0_reg <= Q0_oreg;
	Q1_reg <= Q1_oreg;
end

always @(negedge CLK) begin
	Q1_oreg <= D;
end

specify

    (CLK => Q0) = (0:0:0, 0:0:0);
    (CLK => Q1) = (0:0:0, 0:0:0);
    (CLEAR => Q0) = (0:0:0, 0:0:0);
    (CLEAR => Q1) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge CLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge CLK, negedge D, 0:0:0, 0:0:0);

	$recrem (negedge CLEAR, posedge CLK, 0:0:0, 0:0:0);
	$recrem (negedge CLEAR, negedge CLK, 0:0:0, 0:0:0);    
    
	$period (posedge CLK, 0:0:0);
	$period (posedge CLEAR, 0:0:0);
    $width (posedge CLK, 0:0:0);
    $width (negedge CLK, 0:0:0);
    $width (posedge CLEAR, 0:0:0);

   specparam PATHPULSE$ = 0;

endspecify

endmodule //IDDRC (ddr input, asynchronous clear)


module IDDR_MEM (Q0, Q1, D, WADDR, RADDR, PCLK, ICLK, RESET);

parameter GSREN = "false";  //"true"; "false"
parameter LSREN = "true";    //"true"; "false"

input D, ICLK, PCLK;
input [2:0] WADDR;
input [2:0] RADDR;
input RESET;
output  Q0,Q1;
wire grstn;
wire lrstn;
//synthesis translate_off
assign grstn = GSREN == "true" ? GSR.GSRO : 1'b1;
assign lrstn = LSREN == "true" ? (~RESET) : 1'b1;

reg Dd0;
reg [7:0] D0_mem;
reg [7:0] D1_mem;
reg [1:0] Q_data;

always @(posedge ICLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Dd0 <= 0;
   else if (!lrstn)
      Dd0 <= 0;
   else 
      Dd0 <= D;

always @(negedge ICLK or negedge grstn or negedge lrstn)
   if (!grstn)
      D0_mem <= 0;
   else if (!lrstn)
      D0_mem <= 0;
   else 
      D0_mem[WADDR] <= Dd0;

always @(negedge ICLK or negedge grstn or negedge lrstn)
   if (!grstn)
      D1_mem <= 0;
   else if (!lrstn)
      D1_mem <= 0;
   else 
      D1_mem[WADDR] <= D;

always @(posedge PCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Q_data <= 0;
   else if (!lrstn)
      Q_data <= 0;
   else
      Q_data <= {D1_mem[RADDR], D0_mem[RADDR]};

assign {Q1,Q0}= Q_data;
//synthesis translate_on

specify

    if (PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
    if (PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
    (RESET => Q0) = (0:0:0, 0:0:0);
    (RESET => Q1) = (0:0:0, 0:0:0);

	$setuphold (posedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge ICLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge D, 0:0:0, 0:0:0);

	$setuphold (negedge ICLK, posedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[2], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[2], 0:0:0, 0:0:0);

	$setuphold (posedge PCLK, posedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge RADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge RADDR[2], 0:0:0, 0:0:0);

	$recrem (negedge RESET, posedge ICLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge ICLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	
	$period (posedge ICLK, 0:0:0);
	$period (posedge PCLK, 0:0:0);
    $width (posedge ICLK, 0:0:0);
    $width (negedge ICLK, 0:0:0);
    $width (posedge PCLK, 0:0:0);
    $width (negedge PCLK, 0:0:0);
	$width (posedge RESET, 0:0:0);

   specparam PATHPULSE$ = 0;

endspecify

endmodule // IDDR_MEM (ddr input with asynchronous preset)

module ODDR (Q0, Q1, D0, D1, TX, CLK);

input D0;
input D1;
input TX;
input CLK;
output Q0;
output Q1;

parameter TXCLK_POL = 1'b0; //1'b0:Rising edge output; 1'b1:Falling edge output
parameter INIT = 1'b0;

reg Dd0_0,Dd0_1,Dd0_2;
reg Dd1_0,Dd1_1,Dd1_2;
reg Ttx0,Ttx1,DT0,DT1;
wire gsrt = GSR.GSRO;

initial begin
    Dd0_0 = 1'b0;
    Dd0_1 = 1'b0;
    Dd0_2 = 1'b0;
    Dd1_0 = 1'b0;
    Dd1_1 = 1'b0;
    Dd1_2 = 1'b0;
    Ttx0 = 1'b0;
    Ttx1 = 1'b0;
    DT0 = 1'b0;
    DT1 = 1'b0;
end

always @(gsrt) begin
	if(!gsrt) begin
        assign Dd1_2 = INIT;
		assign Dd0_2 = INIT;
        assign Dd1_1 = INIT;
		assign Dd0_1 = INIT;
        assign Dd1_0 = INIT;
		assign Dd0_0 = INIT;
        assign Ttx0 = INIT;
        assign Ttx1 = INIT;
        assign DT0 = INIT;
        assign DT1 = INIT;
	end
	else begin
		deassign Dd1_2;
		deassign Dd0_2;
        deassign Dd1_1;
		deassign Dd0_1;
        deassign Dd1_0;
		deassign Dd0_0;
		deassign Ttx0;
		deassign Ttx1;
		deassign DT0;
		deassign DT1;
	end
end

always @(posedge CLK) begin
	Dd0_0 <= D0;
	Dd1_0 <= D1;
    Dd0_1 <= Dd0_0;
	Dd1_1 <= Dd1_0;
    Ttx0 <= TX;
    Ttx1 <= Ttx0;
end

always @(posedge CLK) begin
	Dd1_2 <= Dd1_1;
    DT0 <= DT1;
end

always @(negedge CLK) begin
	Dd0_2 <= Dd0_1;
    DT1 <= Ttx1;
end

assign Q0 = (CLK)? Dd0_2 : Dd1_2;
assign Q1 = (TXCLK_POL == 1'b0) ? DT0 : DT1;

specify

	(CLK => Q0) = (0:0:0, 0:0:0);
	(CLK => Q1) = (0:0:0, 0:0:0);
	
	$setuphold (posedge CLK, posedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge TX, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge TX, 0:0:0, 0:0:0);

	$period (posedge CLK, 0:0:0);
    $width (posedge CLK, 0:0:0);
    $width (negedge CLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
endspecify

endmodule // ODDR (ddr output)

module ODDRC (Q0, Q1, D0, D1, TX, CLK, CLEAR);

input D0, D1, TX, CLK, CLEAR;
output Q0,Q1;

parameter TXCLK_POL = 1'b0; //1'b0:Rising edge output; 1'b1:Falling edge output
parameter INIT = 1'b0;

wire gsrt = GSR.GSRO;

reg Dd0_0,Dd0_1,Dd0_2;
reg Dd1_0,Dd1_1,Dd1_2;
reg Ttx0,Ttx1,DT0,DT1;

initial begin
    Dd0_0 = 1'b0;
    Dd0_1 = 1'b0;
    Dd0_2 = 1'b0;
    Dd1_0 = 1'b0;
    Dd1_1 = 1'b0;
    Dd1_2 = 1'b0;
    Ttx0 = 1'b0;
    Ttx1 = 1'b0;
    DT0 = 1'b0;
    DT1 = 1'b0;
end

always @(gsrt or CLEAR) begin
	if(!gsrt) begin
		assign Dd1_2 = INIT;
		assign Dd0_2 = INIT;
        assign Dd1_1 = INIT;
		assign Dd0_1 = INIT;
        assign Dd1_0 = INIT;
		assign Dd0_0 = INIT;
	    assign Ttx0 = INIT;
        assign Ttx1 = INIT;
        assign DT0 = INIT;
        assign DT1 = INIT;
    end
	else if(CLEAR) begin
		assign Dd1_2 = 1'b0;
		assign Dd0_2 = 1'b0;
        assign Dd1_1 = 1'b0;
		assign Dd0_1 = 1'b0;
        assign Dd1_0 = 1'b0;
		assign Dd0_0 = 1'b0;
        assign Ttx0 = INIT;
        assign Ttx1 = INIT;
        assign DT0 = INIT;
        assign DT1 = INIT;
	end
	else begin
		deassign Dd1_2;
		deassign Dd0_2;
        deassign Dd1_1;
		deassign Dd0_1;
        deassign Dd1_0;
		deassign Dd0_0;
        deassign Ttx0;
		deassign Ttx1;
		deassign DT0;
		deassign DT1;
	end
end

always @(posedge CLK) begin
	Dd0_0 <= D0;
	Dd1_0 <= D1;
    Dd0_1 <= Dd0_0;
	Dd1_1 <= Dd1_0;
    Ttx0 <= TX;
    Ttx1 <= Ttx0;
end

always @(posedge CLK) begin
	Dd1_2 <= Dd1_1;
    DT0 <= DT1;
end

always @(negedge CLK) begin
	Dd0_2 <= Dd0_1;
    DT1 <= Ttx1;    
end

assign Q0 = (CLK)? Dd0_2 : Dd1_2;
assign Q1 = (TXCLK_POL == 1'b0) ? DT0 : DT1;

specify

    (CLK => Q0) = (0:0:0, 0:0:0);
    (CLK => Q1) = (0:0:0, 0:0:0);
    (CLEAR => Q0) = (0:0:0, 0:0:0);
    (CLEAR => Q1) = (0:0:0, 0:0:0);

	$setuphold (posedge CLK, posedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, posedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge D1, 0:0:0, 0:0:0);
    $setuphold (posedge CLK, posedge TX, 0:0:0, 0:0:0);
	$setuphold (posedge CLK, negedge TX, 0:0:0, 0:0:0);
    
	$recrem (negedge CLEAR, posedge CLK, 0:0:0, 0:0:0);
	$recrem (negedge CLEAR, negedge CLK, 0:0:0, 0:0:0);

	$period (posedge CLK, 0:0:0);
    $width (posedge CLK, 0:0:0);
    $width (negedge CLK, 0:0:0);

    specparam PATHPULSE$ = 0;

endspecify

endmodule // ODDRC (ddr output with asynchronous clear)


module ODDR_MEM (Q0, Q1, D0, D1, TX, PCLK, TCLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";    //"true"; "false"
parameter TCLK_SOURCE = "DQSW"; //"DQSW","DQSW270"
parameter TXCLK_POL = 1'b0; //1'b0:Rising edge output; 1'b1:Falling edge output

input D0, D1;
input TX, PCLK, TCLK, RESET;
output  Q0, Q1;

//synthesis translate_off
reg [1:0] Dd1;
reg Ttx1;
reg [1:0] Dd2;
reg Ttx2;
reg Qq0;
reg DT0,DT1;
reg Qq1;
wire tclk_sig;
wire grstn;
wire lrstn;

assign grstn = GSREN == "true" ? GSR.GSRO : 1'b1;
assign lrstn = LSREN == "true" ? (~RESET) : 1'b1;
assign tclk_sig = (TCLK_SOURCE == "DQSW") ? TCLK : ~TCLK;

always @(posedge PCLK or negedge grstn or negedge lrstn)
   if (!grstn) begin
      Dd1 <= 2'b0;
      Ttx1 <= 1'b0;
   end
   else if (!lrstn) begin
      Dd1 <= 0;
      Ttx1 <= 0;
   end
   else begin
      	Dd1 <= {D1, D0};
      	Ttx1 <= TX;
   end

always @(posedge tclk_sig or negedge grstn or negedge lrstn)
   if (!grstn) begin
      Dd2 <= 2'b0;
      Ttx2 <= 1'b0;
   end
   else if (!lrstn) begin
      Dd2 <= 2'b0;
      Ttx2 <= 1'b0;
   end
   else begin
      Dd2 <= Dd1;
      Ttx2 <= Ttx1;
   end

always @(posedge tclk_sig or negedge grstn or negedge lrstn)
   if (!grstn) begin
      Qq0 <= 1'b0;
      DT0 <= 1'b0;
   end
   else if (!lrstn) begin
      Qq0 <= 1'b0;
      DT0 <= 1'b0;
   end
   else begin
      Qq0 <= Dd2[1];
      DT0 <= DT1;
   end

always @(negedge tclk_sig or negedge grstn or negedge lrstn)
   if (!grstn) begin
      Qq1 <= 1'b0;
      DT1 <= 1'b0;
   end
   else if (!lrstn) begin
      Qq1 <= 1'b0;
      DT1 <= 1'b0;
   end
   else begin
      Qq1 <= Dd2[0];
      DT1 <= Ttx2;
   end

assign Q0 = tclk_sig ? Qq1 : Qq0;
assign Q1 = (TXCLK_POL == 1'b0) ? DT0 : DT1;

//synthesis translate_on

specify

	(TCLK => Q0) = (0:0:0, 0:0:0);
	(TCLK => Q1) = (0:0:0, 0:0:0);
	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	
	$setuphold (posedge PCLK, posedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge TX, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge TX, 0:0:0, 0:0:0);
		
	$recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge TCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge TCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge TCLK, 0:0:0);
	
    $width (posedge PCLK, 0:0:0);
	$width (posedge TCLK, 0:0:0);
    $width (negedge TCLK, 0:0:0);
	
	$width (posedge RESET, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

endmodule // ODDR_MEM (ddr output with memory)


module IDES4 (Q0, Q1, Q2, Q3, D, CALIB, PCLK, FCLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";    //"true"; "false"

input D, FCLK, PCLK, CALIB, RESET;
output Q0,Q1,Q2,Q3;
wire grstn;
wire lrstn; 
//synthesis translate_off

assign grstn = (GSREN == "true") ? GSR.GSRO : 1'b1;
assign lrstn = (LSREN == "true") ? (~RESET) : 1'b1;

reg Dd0,Dd1;
reg [3:0] D_data,data;
reg D_en1,D_en;
reg Dd_sel,calib_state;
reg [3:0] Q_data;
reg reset_delay;
wire CALIBdata_rising_p;
reg [2:0] CALIBdata;
wire dcnt_en;
reg Dd0_reg0,Dd0_reg1,Dd1_reg0,Dd1_reg1;

initial begin
    calib_state = 1'b0;
    D_en1 = 1'b0;
    D_en = 1'b0;
    Dd_sel = 1'b0;
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Dd0 <= 1'b0;
    end else if (!lrstn) begin
        Dd0 <= 1'b0;
    end else begin
        Dd0 <= D;
    end
end

always @(negedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Dd1 <= 1'b0;
    end else if (!lrstn) begin
        Dd1 <= 1'b0;
    end else begin
        Dd1 <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
    end else if (!lrstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
    end else begin
        Dd0_reg0 <= Dd0;
        Dd0_reg1 <= Dd0_reg0;
        Dd1_reg0 <= Dd1;
        Dd1_reg1 <= Dd1_reg0;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 1'b0;
    end else if (!lrstn) begin
        reset_delay <= 1'b0;
    end else begin
        reset_delay <= 1'b1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        CALIBdata <= 3'b0;
    end else begin
        CALIBdata <= {CALIBdata[1:0], CALIB};
    end
end

assign CALIBdata_rising_p =  CALIBdata[1] && (~CALIBdata[2]);
assign dcnt_en = ~(CALIBdata_rising_p && calib_state);

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_state <= 1'b0;
        D_en1 <= 1'b0;
        D_en  <= 1'b0;
        Dd_sel <= 1'b0;
    end else begin
        D_en <= ~D_en1;
        if (CALIBdata_rising_p) begin
            calib_state <= ~calib_state;
            Dd_sel <= ~Dd_sel;
        end else begin
            calib_state <= calib_state;
            Dd_sel <= Dd_sel;
        end
        
        if (dcnt_en) begin
            D_en1 <= ~D_en1;
        end else begin
            D_en1 <= D_en1;
        end
    end
end

always @(Dd_sel or Dd0 or Dd0_reg0 or Dd0_reg1 or Dd1_reg0 or Dd1_reg1) begin
    if(Dd_sel) begin
        D_data[3] = Dd0;
        D_data[2] = Dd1_reg0;
        D_data[1] = Dd0_reg0;
        D_data[0] = Dd1_reg1;
    end else begin
        D_data[3] = Dd1_reg0;
        D_data[2] = Dd0_reg0;
        D_data[1] = Dd1_reg1;
        D_data[0] = Dd0_reg1;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        data <= 4'b0;
    end else if (!lrstn) begin
        data <= 4'b0;
    end else if (D_en) begin
        data <= D_data;
    end
end

always @(posedge PCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Q_data <= 4'b0;
    end else if (!lrstn) begin
        Q_data <= 4'b0;
    end else begin
        Q_data <= data;
    end
end

assign {Q3,Q2,Q1,Q0} = Q_data;
//synthesis translate_on

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);

	if(RESET) (RESET => Q0) = (0:0:0, 0:0:0);
	if(RESET) (RESET => Q1) = (0:0:0, 0:0:0);
	if(RESET) (RESET => Q2) = (0:0:0, 0:0:0);
	if(RESET) (RESET => Q3) = (0:0:0, 0:0:0);

	$setuphold (posedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, negedge D, 0:0:0, 0:0:0);

    $setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
		
	$recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	
	specparam PATHPULSE$ = 0;
	
endspecify

endmodule // IDES4 (4 to 1 deserializer)


module IDES4_MEM (Q0, Q1, Q2, Q3, D, WADDR, RADDR, CALIB, PCLK, FCLK, ICLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";    //"true"; "false"

input D, ICLK, FCLK, PCLK;
input [2:0] WADDR;
input [2:0] RADDR;
input RESET,CALIB;
output Q0,Q1,Q2,Q3;
wire grstn,lrstn;
reg Dd0;
reg [3:0] D_data,Q_data, data;
reg D_en1,D_en;
reg Dd_sel,calib_state;
reg reset_delay;
wire CALIBdata_rising_p;
reg [2:0] CALIBdata;
wire dcnt_en;
reg Dd0_reg0,Dd0_reg1,Dd1_reg0,Dd1_reg1;
reg [7:0] D0_mem;
reg [7:0] D1_mem;

initial begin
    calib_state = 1'b0;
    D_en1 = 1'b0;
    D_en = 1'b0;
    Dd_sel = 1'b0;
end

assign grstn = (GSREN == "true") ? GSR.GSRO : 1'b1;
assign lrstn = (LSREN == "true") ? (~RESET) : 1'b1;

always @(posedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Dd0 <= 1'b0;
    end else if (!lrstn) begin
        Dd0 <= 1'b0;
    end else begin
        Dd0 <= D;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        D0_mem <= 8'b0;
    end else if (!lrstn) begin
        D0_mem <= 8'b0;
    end else begin
        D0_mem[WADDR] <= Dd0;
    end
end

always @(negedge ICLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        D1_mem <= 8'b0;
    end else if (!lrstn) begin
        D1_mem <= 8'b0;
    end else begin
        D1_mem[WADDR] <= D;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
    end else if (!lrstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
    end else begin
        Dd0_reg0 <= D0_mem[RADDR];
        Dd0_reg1 <= Dd0_reg0;
        Dd1_reg0 <= D1_mem[RADDR];
        Dd1_reg1 <= Dd1_reg0;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 1'b0;
    end else if (!lrstn) begin
        reset_delay <= 1'b0;
    end else begin
        reset_delay <= 1'b1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        CALIBdata <= 3'b0;
    end else begin
        CALIBdata <= {CALIBdata[1:0], CALIB};
    end
end

assign CALIBdata_rising_p =  CALIBdata[1] && (~CALIBdata[2]);
assign dcnt_en = ~(CALIBdata_rising_p && calib_state);

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        calib_state <= 1'b0;
        D_en1 <= 1'b0;
        D_en  <= 1'b0;
        Dd_sel <= 1'b0;
    end else begin
        D_en <= ~D_en1;
        if (CALIBdata_rising_p) begin
            calib_state <= ~calib_state;
            Dd_sel <= ~Dd_sel;
        end else begin
            calib_state <= calib_state;
            Dd_sel <= Dd_sel;
        end
        
        if (dcnt_en) begin
            D_en1 <= ~D_en1;
        end else begin
            D_en1 <= D_en1;
        end
    end
end

always @(Dd_sel or D0_mem[RADDR] or Dd0_reg0 or Dd0_reg1 or Dd1_reg0 or Dd1_reg1) begin
    if(Dd_sel) begin
        D_data[3] = D0_mem[RADDR];
        D_data[2] = Dd1_reg0;
        D_data[1] = Dd0_reg0;
        D_data[0] = Dd1_reg1;
    end else begin
        D_data[3] = Dd1_reg0;
        D_data[2] = Dd0_reg0;
        D_data[1] = Dd1_reg1;
        D_data[0] = Dd0_reg1;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        data <= 4'b0;
    end else if (!lrstn) begin
        data <= 4'b0;
    end else if (D_en) begin
        data <= D_data;
    end
end

always @(posedge PCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        Q_data <= 4'b0;
    end else if (!lrstn) begin
        Q_data <= 4'b0;
    end else begin
      Q_data <= data;
    end
end

assign {Q3,Q2,Q1,Q0} = Q_data;

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	(RESET => Q2) = (0:0:0, 0:0:0);
	(RESET => Q3) = (0:0:0, 0:0:0);
	
	$setuphold (posedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge ICLK, negedge D, 0:0:0, 0:0:0);    
	$setuphold (negedge ICLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge D, 0:0:0, 0:0:0); 
	
	$setuphold (negedge ICLK, posedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[0], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[1], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, posedge WADDR[2], 0:0:0, 0:0:0);
	$setuphold (negedge ICLK, negedge WADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[0], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[1], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge RADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge RADDR[2], 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
	
    $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge ICLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge ICLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (posedge ICLK, 0:0:0);
	$period (negedge ICLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

endmodule //IDES4_MEM (4 to 1 deserializer with memory)


module IVIDEO (Q0, Q1, Q2, Q3, Q4, Q5, Q6, D, CALIB, PCLK, FCLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";   //"true"; "false"

input D, FCLK, PCLK, CALIB, RESET;
output Q0, Q1, Q2, Q3, Q4, Q5, Q6;
wire grstn;
wire lrstn; 
assign grstn = GSREN == "true" ? GSR.GSRO : 1'b1;
assign lrstn = LSREN == "true" ? (~RESET) : 1'b1;

reg Dd0;
reg Dd1;
reg [6:0] D_data;
reg [6:0] data;
reg [6:0] Q_data;
reg Dd_sel;
reg reset_delay;
wire CALIBdata_rising_p;
reg [2:0] CALIBdata;
wire dcnt_en,dsel_en;
reg Dd0_reg0,Dd0_reg1,Dd0_reg2,Dd1_reg0,Dd1_reg1,Dd1_reg2,Dd1_reg3;
reg D_en,D_en0,D_en1;


always @(posedge FCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Dd0 <= 0;
   else if (!lrstn)
      Dd0 <= 0;
   else
      Dd0 <= D;

always @(negedge FCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Dd1 <= 0;
   else if (!lrstn)
      Dd1 <= 0;
   else
      Dd1 <= D;

always @(posedge FCLK or negedge grstn or negedge lrstn) begin
    if (!grstn) begin
        reset_delay <= 1'b0;
    end else if (!lrstn) begin
        reset_delay <= 1'b0;
    end else begin
        reset_delay <= 1'b1;
    end
end

always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        CALIBdata <= 3'b0;
    end else begin
        CALIBdata <= {CALIBdata[1:0], CALIB};
    end
end

assign CALIBdata_rising_p =  CALIBdata[1] && (~CALIBdata[2]);
assign dcnt_en = ~CALIBdata_rising_p;
assign dsel_en = (Dd_sel & D_en1 & (~D_en0) & (~CALIBdata_rising_p)) | ((~Dd_sel) & D_en0 & D_en1);
always @(posedge FCLK or negedge reset_delay) begin
    if (!reset_delay) begin
        D_en1 <= 1'b0;
        D_en0 <= 1'b0;
        D_en  <= 1'b0;
        Dd_sel <= 1'b0;
    end else begin
        D_en <= (~((~Dd_sel) | D_en0 | D_en1)) | (~(Dd_sel | D_en1 | (~D_en0)));
        if (dsel_en) begin
            Dd_sel <= ~Dd_sel;
        end else begin
            Dd_sel <= Dd_sel;
        end
        
        if (dcnt_en) begin
            D_en0 <= ~(D_en0 | (Dd_sel & D_en1 & (~D_en0)));
        end else  begin
            D_en0 <= D_en0;
        end
                                                                                   
        if (dcnt_en) begin
            D_en1 <= (~(Dd_sel & D_en1 & (~D_en0))) &(D_en0 ^ D_en1);
        end else begin
            D_en1 <= D_en1;
        end    
    end    
        
end

always @(posedge FCLK or negedge grstn  or negedge lrstn) begin
    if (!grstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd0_reg2 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
        Dd1_reg2 <= 1'b0;
        Dd1_reg3 <= 1'b0;
    end else if(!lrstn) begin
        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd0_reg2 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
        Dd1_reg2 <= 1'b0;
        Dd1_reg3 <= 1'b0;
    end else begin
        Dd0_reg0 <= Dd0;
        Dd0_reg1 <= Dd0_reg0;
        Dd0_reg2 <= Dd0_reg1;
        Dd1_reg0 <= Dd1;
        Dd1_reg1 <= Dd1_reg0;
        Dd1_reg2 <= Dd1_reg1;
        Dd1_reg3 <= Dd1_reg2;
    end
end

always @(Dd_sel or Dd0 or Dd0_reg0 or Dd0_reg1 or Dd0_reg2 or Dd1_reg0 or Dd1_reg1 or Dd1_reg2 or Dd1_reg3) begin
    if(Dd_sel) begin
        D_data[6] <= Dd0;
        D_data[5] <= Dd1_reg0;
        D_data[4] <= Dd0_reg0;
        D_data[3] <= Dd1_reg1;
        D_data[2] <= Dd0_reg1;
        D_data[1] <= Dd1_reg2;
        D_data[0] <= Dd0_reg2;
    end else begin
        D_data[6] <= Dd1_reg0;
        D_data[5] <= Dd0_reg0;
        D_data[4] <= Dd1_reg1;
        D_data[3] <= Dd0_reg1;
        D_data[2] <= Dd1_reg2;
        D_data[1] <= Dd0_reg2;
        D_data[0] <= Dd1_reg3;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      data <= 0;
   else if (!lrstn)
      data <= 0;
   else if (D_en)
      data <= D_data;


always @(posedge PCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Q_data <= 0;
   else if (!lrstn)
      Q_data <= 0;
   else
      Q_data <= data;

assign {Q6, Q5, Q4, Q3, Q2, Q1, Q0} = Q_data;

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q4) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q5) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q6) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	(RESET => Q2) = (0:0:0, 0:0:0);
	(RESET => Q3) = (0:0:0, 0:0:0);
	(RESET => Q4) = (0:0:0, 0:0:0);
	(RESET => Q5) = (0:0:0, 0:0:0);
	(RESET => Q6) = (0:0:0, 0:0:0);
	
	$setuphold (posedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge D, 0:0:0, 0:0:0);   
	$setuphold (negedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, negedge D, 0:0:0, 0:0:0);  
	
