always @(posedge FCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      data <= 0;
   else if (!lrstn)
      data <= 0;
   else if (D_en)
      data <= D_data;

always @(posedge PCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Q_data <= 0;
   else if (!lrstn)
      Q_data <= 0;
   else
      Q_data <= data;

assign {Q7, Q6, Q5, Q4, Q3, Q2, Q1, Q0} = Q_data;

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q4) = (0:0:0, 0:0:0);
