	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

