        Dd0_reg0 <= 1'b0;
        Dd0_reg1 <= 1'b0;
        Dd0_reg2 <= 1'b0;
        Dd0_reg3 <= 1'b0;
        Dd0_reg4 <= 1'b0;
        Dd1_reg0 <= 1'b0;
        Dd1_reg1 <= 1'b0;
        Dd1_reg2 <= 1'b0;
        Dd1_reg3 <= 1'b0;
        Dd1_reg4 <= 1'b0;        
    end else begin
        Dd0_reg0 <= Dd0;
        Dd0_reg1 <= Dd0_reg0;
        Dd0_reg2 <= Dd0_reg1;
        Dd0_reg3 <= Dd0_reg2;
        Dd0_reg4 <= Dd0_reg3;
        Dd1_reg0 <= Dd1;
        Dd1_reg1 <= Dd1_reg0;
        Dd1_reg2 <= Dd1_reg1;
        Dd1_reg3 <= Dd1_reg2;
        Dd1_reg4 <= Dd1_reg3;
    end
end

always @(Dd_sel or Dd0 or Dd0_reg0 or Dd0_reg1 or Dd0_reg2 or Dd0_reg3 or Dd0_reg4 or Dd1_reg0 or Dd1_reg1 or Dd1_reg2 or Dd1_reg3 or Dd1_reg4) begin
    if(Dd_sel) begin
        D_data[9] <= Dd0;
        D_data[8] <= Dd1_reg0;
        D_data[7] <= Dd0_reg0;
        D_data[6] <= Dd1_reg1;
        D_data[5] <= Dd0_reg1;
        D_data[4] <= Dd1_reg2;
        D_data[3] <= Dd0_reg2;
        D_data[2] <= Dd1_reg3;
        D_data[1] <= Dd0_reg3;
        D_data[0] <= Dd1_reg4;
    end else begin
        D_data[9] <= Dd1_reg0;
        D_data[8] <= Dd0_reg0;
        D_data[7] <= Dd1_reg1;
        D_data[6] <= Dd0_reg1;
        D_data[5] <= Dd1_reg2;
        D_data[4] <= Dd0_reg2;
        D_data[3] <= Dd1_reg3;
        D_data[2] <= Dd0_reg3;
        D_data[1] <= Dd1_reg4;
        D_data[0] <= Dd0_reg4;
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      data <= 0;
   else if (!lrstn)
      data <= 0;
   else if (D_en)
      data <= D_data;

always @(posedge PCLK or negedge grstn or negedge lrstn)
   if (!grstn)
      Q_data <= 0;
   else if (!lrstn)
      Q_data <= 0;
   else
      Q_data <= data;

assign {Q9, Q8, Q7, Q6, Q5, Q4, Q3, Q2, Q1, Q0} = Q_data;

//synthesis translate_on

specify

	if(PCLK) (PCLK => Q0) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q1) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q2) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q3) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q4) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q5) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q6) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q7) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q8) = (0:0:0, 0:0:0);
	if(PCLK) (PCLK => Q9) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	(RESET => Q2) = (0:0:0, 0:0:0);
	(RESET => Q3) = (0:0:0, 0:0:0);
	(RESET => Q4) = (0:0:0, 0:0:0);
	(RESET => Q5) = (0:0:0, 0:0:0);
	(RESET => Q6) = (0:0:0, 0:0:0);
	(RESET => Q7) = (0:0:0, 0:0:0);
	(RESET => Q8) = (0:0:0, 0:0:0);
	(RESET => Q9) = (0:0:0, 0:0:0);
	
    $setuphold (posedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, posedge D, 0:0:0, 0:0:0);
	$setuphold (negedge FCLK, negedge D, 0:0:0, 0:0:0);

	$setuphold (posedge FCLK, posedge CALIB, 0:0:0, 0:0:0);
	$setuphold (posedge FCLK, negedge CALIB, 0:0:0, 0:0:0);
	
    $recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
endspecify

endmodule // IDES10 (10 to 1 deserializer)

module OSER4 (Q0, Q1, D0, D1, D2, D3, TX0, TX1, PCLK, FCLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";   //"true"; "false"
parameter HWL = "false";     //"true"; "false"
parameter TXCLK_POL = 1'b0; //1'b0:Rising edge output; 1'b1:Falling edge output

input D3, D2, D1, D0;
input TX1, TX0;
input PCLK, FCLK, RESET;
output  Q0, Q1;

//synthesis translate_off
reg [3:0] Dd1,Dd2,Dd3;
reg [1:0] Ttx1,Ttx2,Ttx3;
reg rstn_dsel,dsel,d_up0,d_up1;
wire d_en0,d_en1;
reg Qq_n,Q_data_n,Qq_p,Q_data_p;
wire grstn,lrstn;

initial begin
    dsel = 1'b0;
end

assign grstn = GSREN == "true" ? GSR.GSRO : 1'b1;
assign lrstn = LSREN == "true" ? (~RESET) : 1'b1;

always @(posedge PCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn) begin
        Dd1 <= 4'b0;
        Ttx1 <= 2'b0;
    end
    else if (!lrstn) begin
        Dd1 <= 4'b0;
        Ttx1 <= 2'b0;
    end
    else begin
        Dd1 <= {D3,D2,D1,D0};
        Ttx1 <= {TX1,TX0};
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if(!grstn) begin
        rstn_dsel <= 1'b0;
    end
    else if (!lrstn) begin
        rstn_dsel <= 1'b0;        
    end
    else begin
        rstn_dsel <= 1'b1;
    end
end

always @(posedge FCLK or negedge rstn_dsel) 
begin
    if (!rstn_dsel) begin
        dsel <= 1'b0;
    end else begin
        dsel <= ~dsel;
    end
end

assign d_en0 = ~dsel;
assign d_en1 = (HWL == "true") ? (~dsel) : dsel;

always @(posedge FCLK or negedge rstn_dsel)
begin
    if (!rstn_dsel) begin
        d_up0 <= 1'b0;
        d_up1 <= 1'b0;
    end else begin
        if(d_en0)begin
            d_up0 <= 1'b1;
        end else begin
            d_up0 <= 1'b0;
        end

        if(d_en1)begin
            d_up1 <= 1'b1;
        end else begin
            d_up1 <= 1'b0;
        end
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn) begin
        Dd2 <= 4'b0;
        Ttx2 <= 2'b0;
    end else if (!lrstn) begin
        Dd2 <= 4'b0;
        Ttx2 <= 2'b0;
    end else begin
        if(d_up0)begin
            Dd2 <= Dd1;
            Ttx2 <= Ttx1;
        end else begin
            Dd2 <= Dd2;
            Ttx2 <= Ttx2;
        end
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)begin
   if (!grstn) begin
      Dd3 <= 4'b0;
      Ttx3 <= 2'b0;
   end else if (!lrstn) begin
      Dd3 <= 4'b0;
      Ttx3 <= 2'b0;
   end else begin
        if(d_up1)begin
            Dd3 <= Dd2;
            Ttx3 <= Ttx2;
        end else begin
            Dd3[0] <= Dd3[2];
            Dd3[2] <= 1'b0;
            Dd3[1] <= Dd3[3];
            Dd3[3] <= 1'b0;
            Ttx3[0] <= Ttx3[1];
            Ttx3[1] <= 1'b0;
        end
    end
end

always @(negedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn) begin
        Qq_n <= 1'b0;
        Q_data_n <= 1'b0; 
    end else if (!lrstn) begin
        Qq_n <= 1'b0;
        Q_data_n <= 1'b0; 
    end else begin
        Qq_n <= Dd3[0];
        Q_data_n <= Ttx3[0];
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn) begin
        Qq_p <= 1'b0;
    end else if(!lrstn) begin
        Qq_p <= 1'b0;
    end else begin
        Qq_p <= Dd3[1];
    end
end

always @(posedge FCLK or negedge grstn or negedge lrstn)
begin
    if (!grstn) begin
        Q_data_p <= 1'b0;
    end else if (!lrstn) begin
        Q_data_p <= 1'b0;
    end else begin
        Q_data_p <= Q_data_n;
    end
end

assign Q0 = FCLK ? Qq_n : Qq_p;
assign Q1 = (TXCLK_POL == 1'b0) ? Q_data_p : Q_data_n;

//synthesis translate_on

specify

	(FCLK => Q0) = (0:0:0, 0:0:0);
	(FCLK => Q1) = (0:0:0, 0:0:0);

	(RESET => Q0) = (0:0:0, 0:0:0);
	(RESET => Q1) = (0:0:0, 0:0:0);
	
	$setuphold (posedge PCLK, posedge D3, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D3, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge D2, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D2, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge D0, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge TX1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge TX1, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, posedge TX0, 0:0:0, 0:0:0);
	$setuphold (posedge PCLK, negedge TX0, 0:0:0, 0:0:0);

	$recrem (negedge RESET, posedge PCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, posedge FCLK, 0:0:0, 0:0:0);
	$recrem (negedge RESET, negedge FCLK, 0:0:0, 0:0:0);
		
	$period (posedge PCLK, 0:0:0);
	$period (posedge FCLK, 0:0:0);
	$period (negedge FCLK, 0:0:0);

	specparam PATHPULSE$ = 0;
	
    endspecify

endmodule // OSER4 (4 to 1 serializer)

module OSER4_MEM (Q0, Q1, D0, D1, D2, D3, TX0, TX1, PCLK, FCLK, TCLK, RESET);

parameter GSREN = "false"; //"true"; "false"
parameter LSREN = "true";    //"true"; "false"
parameter HWL = "false";     //"true"; "false"
parameter TCLK_SOURCE = "DQSW"; //"DQSW","DQSW270"
parameter TXCLK_POL = 1'b0; //1'b0:Rising edge output; 1'b1:Falling edge output

input D0, D1, D2, D3;
input TX0, TX1;
input PCLK, FCLK, TCLK, RESET;
