       	$setuphold (posedge CLKB, posedge BLKSEL[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge BLKSEL[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, posedge BLKSEL[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge BLKSEL[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge CEA, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge CEA, 0:0:0, 0:0:0);
        $setuphold (posedge CLKB, posedge CEB, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge CEB, 0:0:0, 0:0:0);
        $setuphold (posedge CLKB, posedge OCE, 0:0:0, 0:0:0);
