       	$setuphold (posedge CLKA, negedge DI[4], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[5], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[5], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[6], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[6], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[7], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[7], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[8], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[8], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[9], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[9], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[10], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[10], 0:0:0, 0:0:0);
