       	$setuphold (posedge CLKA, negedge DI[11], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[12], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[12], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[13], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[13], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge DI[14], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge DI[14], 0:0:0, 0:0:0);
