       	$setuphold (posedge CLKB, negedge DIB[16], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, posedge DIB[17], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge DIB[17], 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge BLKSELA[0], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge BLKSELA[0], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge BLKSELA[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge BLKSELA[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge BLKSELA[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge BLKSELA[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, posedge BLKSELB[0], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge BLKSELB[0], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, posedge BLKSELB[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge BLKSELB[1], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, posedge BLKSELB[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge BLKSELB[2], 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, posedge CEA, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge CEA, 0:0:0, 0:0:0);
        $setuphold (posedge CLKB, posedge CEB, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge CEB, 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge OCEA, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge OCEA, 0:0:0, 0:0:0);
	    $setuphold (posedge CLKB, posedge OCEB, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge OCEB, 0:0:0, 0:0:0);
	    $setuphold (posedge CLKA, posedge RESETA, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge RESETA, 0:0:0, 0:0:0);
        $setuphold (posedge CLKB, posedge RESETB, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge RESETB, 0:0:0, 0:0:0);
        $setuphold (posedge CLKA, posedge WREA, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKA, negedge WREA, 0:0:0, 0:0:0);
        $setuphold (posedge CLKB, posedge WREB, 0:0:0, 0:0:0);
       	$setuphold (posedge CLKB, negedge WREB, 0:0:0, 0:0:0);
	
       	$recrem (negedge RESETA, posedge CLKA, 0:0:0, 0:0:0);
       	$recrem (negedge RESETB, posedge CLKB, 0:0:0, 0:0:0);
       	$period (posedge CLKA, 0:0:0);
        $period (posedge CLKB, 0:0:0);
	
        $width (posedge CLKA, 0:0:0);
        $width (negedge CLKA, 0:0:0);
        $width (posedge CLKB, 0:0:0);
        $width (negedge CLKB, 0:0:0);
        specparam PATHPULSE$ = 0;

endspecify

endmodule // DPX9B: true dual port 18k Block SRAM


//DLL
module DLL (STEP, LOCK, UPDNCNTL, STOP, CLKIN, RESET);

input CLKIN;
input STOP;
input UPDNCNTL;
input RESET;

output [7:0]STEP;
output LOCK;

parameter DLL_FORCE = 0;//1: force lock and code; 0: code/lock generated from DLL loop
parameter CODESCAL="000";//001 010 011 100 101 110 111
parameter SCAL_EN="true";//true,false
parameter DIV_SEL = 1'b0; // 1'b0,normal lock mode; 1'b1,fast lock mode

reg inner_period,osc_clk_out;
realtime clkin_edge,clkin_period,clkin_period_pre;
real del;
reg [7:0]step_reg,step_reg_sig;
reg stop_0,stop_1n;
integer cnt;
reg clk_effect,lock_reg;
wire reset_sig;
wire grstn = GSR.GSRO;

initial
begin
del=0.025;
clk_effect = 1'b0;
step_reg = 8'b00000000;
lock_reg = 1'b0;
end

    assign reset_sig = RESET | (~grstn);    

    always @(posedge CLKIN or posedge reset_sig) begin
        if(reset_sig) begin
            clk_effect <= 0;
            clkin_period <= 0;
        end else begin
            clkin_edge<=$realtime;
            clkin_period<=$realtime-clkin_edge;
            clkin_period_pre<=clkin_period;
        end

        if(clkin_period > 0) begin    
            if((clkin_period-clkin_period_pre <0.001) &&(clkin_period-clkin_period_pre>-0.001)) begin
                clk_effect = 1;
            end else begin
                clk_effect = 0;
            end
        end
           
    end

    always @ (negedge CLKIN or posedge reset_sig) begin
        if (reset_sig) begin
            stop_0 <= 1'b0;
        end else begin
            stop_0 <= STOP;
        end
    end

    always @ (negedge CLKIN or posedge reset_sig) begin
        if (reset_sig) begin
            stop_1n <= 1'b1;
        end else begin
            stop_1n <= ~stop_0;
        end
    end

    assign clk_out = CLKIN && stop_1n;

    always @(posedge clk_out or posedge reset_sig) begin
        if (reset_sig) begin
            cnt <= 0;
            lock_reg <= 1'b0;
        end else begin
            cnt <= cnt + 1;
            if(DIV_SEL == 1'b0) begin
                if(cnt >= 33600) begin
                    lock_reg <= 1'b1;
                end else begin                
                    lock_reg <= 1'b0;
                end               
            end

            if(DIV_SEL == 1'b1) begin
                if(cnt >= 2100) begin
                    lock_reg <= 1'b1;
                end else begin                
                    lock_reg <= 1'b0;
                end               
            end
        end
    end

    assign LOCK = (DLL_FORCE==1) ? 1'b1: lock_reg;

    always @(*) begin
        if(clk_effect) begin
            if(SCAL_EN=="true") begin
                case(CODESCAL)
                    "000": step_reg<=clkin_period/del/360*101;
                    "001": step_reg<=clkin_period/del/360*112;
                    "010": step_reg<=clkin_period/del/360*123;
                    "011": step_reg<=clkin_period/del/360*135;
                    "100": step_reg<=clkin_period/del/360*79;
                    "101": step_reg<=clkin_period/del/360*68;
                    "110": step_reg<=clkin_period/del/360*57;
                    "111": step_reg<=clkin_period/del/360*45;
                endcase
            end else begin
                step_reg<=clkin_period/del/360*90;
            end
        end
    end

    always @(step_reg or reset_sig or UPDNCNTL)
    begin
        if(reset_sig == 1'b1) begin
            step_reg_sig <= 8'b00000000;
        end else if(UPDNCNTL==0) begin
            step_reg_sig <= step_reg;
        end
    end

    assign STEP = (DLL_FORCE==1) ? 255 : step_reg_sig;

specify

    (CLKIN => STEP[0]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[1]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[2]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[3]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[4]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[5]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[6]) = (0:0:0, 0:0:0);
    (CLKIN => STEP[7]) = (0:0:0, 0:0:0);

    (RESET => STEP[0]) = (0:0:0, 0:0:0);
    (RESET => STEP[1]) = (0:0:0, 0:0:0);
    (RESET => STEP[2]) = (0:0:0, 0:0:0);
    (RESET => STEP[3]) = (0:0:0, 0:0:0);
    (RESET => STEP[4]) = (0:0:0, 0:0:0);
    (RESET => STEP[5]) = (0:0:0, 0:0:0);
    (RESET => STEP[6]) = (0:0:0, 0:0:0);
    (RESET => STEP[7]) = (0:0:0, 0:0:0);
endspecify 

endmodule


