	    (CLK => DOUT[49]) = (0:0:0, 0:0:0);
	    (CLK => DOUT[50]) = (0:0:0, 0:0:0);
	    (CLK => DOUT[51]) = (0:0:0, 0:0:0);
	    (CLK => DOUT[52]) = (0:0:0, 0:0:0);
	    (CLK => DOUT[53]) = (0:0:0, 0:0:0);

	    (RESET => DOUT[0]) = (0:0:0, 0:0:0);
	    (RESET => DOUT[1]) = (0:0:0, 0:0:0);
