input  I, OEN;
bufif0 TB (O, I, OEN);
notif0 YB (OB, I, OEN);

specify

	(I => O) = (0:0:0, 0:0:0);
	(I => OB) = (0:0:0, 0:0:0);   
	(OEN => O) = (0:0:0, 0:0:0);
	(OEN => OB) = (0:0:0, 0:0:0);   
	specparam PATHPULSE$ = 0;

endspecify

endmodule

