        if (IO == 1'b1 && IOB == 1'b0)
            O <= IO;
        else if (IO == 1'b0 && IOB == 1'b1)
            O <= IO;
        else if (IO == 1'bx || IOB == 1'bx)
            O <= 1'bx;
end

specify

	(I => O) = (0:0:0, 0:0:0);
	(IO => O) = (0:0:0, 0:0:0);
	(IO => IOB) = (0:0:0, 0:0:0);   
	(IOB => IO) = (0:0:0, 0:0:0);       
	(OEN => O) = (0:0:0, 0:0:0);
	(IOB => O) = (0:0:0, 0:0:0);
	(I => IO) = (0:0:0, 0:0:0);
	(I => IOB) = (0:0:0, 0:0:0);
	(OEN => IO) = (0:0:0, 0:0:0);
	(OEN => IOB) = (0:0:0, 0:0:0);
	specparam PATHPULSE$ = 0;

endspecify

endmodule

