	(OEN => O) = (0:0:0, 0:0:0);
	(IOB => O) = (0:0:0, 0:0:0);
	(I => IO) = (0:0:0, 0:0:0);
	(I => IOB) = (0:0:0, 0:0:0);
	(OEN => IO) = (0:0:0, 0:0:0);
	(OEN => IOB) = (0:0:0, 0:0:0);
